ensureTranslationTables();

$totalOk = 0; $totalErr = 0;
foreach (['hi', 'gu', 'mr'] as $lang) {
    $rows = [];
    foreach ($translations as $key => $byLang) {
        $rows[] = ['entity_id' => $key, 'field_key' => 'value', 'value' => $byLang[$lang]];
    }
    $result = saveTranslations('ui_string', $lang, $rows);
    if ($result['success']) {
        echo "[$lang] Seeded " . count($rows) . " ui_string translations.\n";
        $totalOk += count($rows);
    } else {
        echo "[$lang] FAILED: " . $result['error'] . "\n";
        $totalErr++;
    }
}

echo "\nDone. $totalOk rows upserted across hi/gu/mr" . ($totalErr ? ", $totalErr language(s) failed." : ".") . "\n";
